// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import { DataTable } from "../db/DataTable.sol";
import { DEPLOYER_ROLE } from "../constants/RoleConstants.sol";
import {
    ID_CID,
    NAME_CID,
    PLAYER_CID,
    TIMESTAMP_CID,
    UINT256_COL_1,
    UINT256_COL_2
} from "../constants/ColumnConstants.sol";
import { ID as GIGA_PET_NFT_ID, IGigaPetNFT } from "../tokens/gigapetnft/IGigaPetNFT.sol";
import { ID as GIGA_PET_TRAITS_ID, IGigaPetTraits } from "../tokens/gigapetnft/IGigaPetTraits.sol";

/// @dev System id for the registry. Mirrors the `game.gigaverse.*` convention.
uint256 constant ID = uint256(keccak256("game.gigaverse.gluefactorysystem.v1"));

// ── Burn record doc (docId = auto-incremented renderId). ──
// Keyed by a unique per-render id rather than petId so that if a pet is ever
// revived (an ERC-721 id can be re-minted after burn) and rendered again, the
// second render is its own record instead of overwriting the first. The
// "can't burn the same live pet twice" guarantee stays on the NFT itself.
// NAME_CID      → BURN_DOC_TYPE tag (backend queries this).
// ID_CID        → renderId (the doc's own id).
// PLAYER_CID    → the burner (who is owed the glue).
// BURN_PET_CID (UINT256_COL_2)    → the rendered petId.
// BURN_RARITY_CID (UINT256_COL_1) → on-chain rarity snapshot at burn time.
// TIMESTAMP_CID → block.timestamp of the burn.
string constant BURN_DOC_TYPE = "glue_burn";
uint256 constant BURN_RARITY_CID = UINT256_COL_1;
uint256 constant BURN_PET_CID = UINT256_COL_2;

uint256 constant RARITY_BANDS = 6;

/// @title GlueFactorySystem
/// @notice Renders a gigling into "glue" by burning the pet NFT (the deflationary
///         sink) and writing a `glue_burn` record doc (keyed by an auto-incremented
///         renderId). The backend reads these records from the indexer and credits
///         the burner the faction-correct glue off-chain — rarity (recorded here)
///         plus faction (off-chain). Nothing is minted on-chain; this contract is
///         the verified burn + its durable, queryable record.
///
///         The NFT's before-update handler stamps the pre-burn owner into
///         GigaPetTraits, so a rendered gigling still resolves in the Hall of Fallen.
contract GlueFactorySystem is DataTable {
    error NotPetOwner();
    error PetNotHatched();
    error InvalidRarity();

    event GiglingRendered(uint256 indexed renderId, uint256 indexed petId, address indexed owner, uint8 rarity);

    constructor(address gameRegistryAddress) DataTable(gameRegistryAddress, ID) { }

    function initialize() external override onlyRole(DEPLOYER_ROLE) {
        initializeTable("GlueFactorySystem", ID);
    }

    /// @notice Burn a gigling you own and record it for off-chain glue crediting.
    ///         Permanently destroys the pet; the backend mints the glue.
    function burnToGlue(uint256 petId) external whenNotPaused whenActive nonReentrant {
        IGigaPetNFT petNft = IGigaPetNFT(_gameRegistry.getSystem(GIGA_PET_NFT_ID));
        if (petNft.ownerOf(petId) != msg.sender) revert NotPetOwner();

        IGigaPetTraits traits = IGigaPetTraits(_gameRegistry.getSystem(GIGA_PET_TRAITS_ID));
        if (!traits.isHatched(petId)) revert PetNotHatched();

        uint8 rarity = traits.getRarity(petId);
        if (rarity < 1 || rarity > RARITY_BANDS) revert InvalidRarity();

        // Burn first (deflation). The GigaPetNFT before-update handler stamps the
        // pre-burn owner into GigaPetTraits → still resolves in Hall of Fallen.
        petNft.burnByGameContract(petId);

        // Record the render under a fresh renderId. The backend reads `glue_burn`
        // docs and credits glue off-chain, locking each by this renderId.
        uint256 renderId = _getAndIncrementAutoIncId();
        _setDocStringValue(renderId, NAME_CID, BURN_DOC_TYPE);
        _setDocUint256Value(renderId, ID_CID, renderId);
        _setDocAddressValue(renderId, PLAYER_CID, msg.sender);
        _setDocUint256Value(renderId, BURN_PET_CID, petId);
        _setDocUint256Value(renderId, BURN_RARITY_CID, rarity);
        _setDocUint256Value(renderId, TIMESTAMP_CID, block.timestamp);

        emit GiglingRendered(renderId, petId, msg.sender, rarity);
    }
}

